fn swap_pair<T>(pair: (T, T)) -> (T, T) {
    (pair.1, pair.0)
}

fn main() {
    let numbers = swap_pair((1, 2));
    let words = swap_pair(("left", "right"));
    let names = swap_pair((String::from("Ana"), String::from("Binh")));
    println!("{:?}", numbers);
    println!("{:?}", words);
    println!("{:?}", names);
}

// Output:
// (2, 1)
// ("right", "left")
// ("Binh", "Ana")

// This does NOT compile. Error E0369: binary operation `>` cannot be applied to type `&T`
fn largest<T>(items: &[T]) -> &T {
    let mut biggest = &items[0];
    for item in items {
        if item > biggest {
            biggest = item;
        }
    }
    biggest
}

fn largest<T: PartialOrd>(items: &[T]) -> &T {
    let mut biggest = &items[0];
    for item in items {
        if item > biggest {
            biggest = item;
        }
    }
    biggest
}

fn main() {
    let numbers = [34, 50, 25, 100, 65];
    let letters = ['y', 'm', 'a', 'q'];
    println!("largest number: {}", largest(&numbers));
    println!("largest letter: {}", largest(&letters));
}

