fn last_item<T>(items: &[T]) -> &T {
    &items[items.len() - 1]
}

fn main() {
    let numbers = [4, 8, 15];
    println!("{}", last_item(&numbers));
    let words = ["red", "green", "blue"];
    println!("{}", last_item(&words));
}
